entries=[]
for rid,name,size,world,palette,subject in rows:
    neutral=rid in ['R2','R7','R8']
    entries.append(dict(id=rid,name=name,file=name+'.png',size=size,world_size_m=world,palette=palette.split(),color_range=[1,6] if neutral else [8,12],neutral_tinted=neutral,seam_axes=['x'] if rid=='R9' else ['x','y'],prompt=COMMON+'\nOutput native size '+str(size[0])+'x'+str(size[1])+'. Palette: '+' '.join('#'+h for h in palette.split())+'.\nSubject: '+subject))
(WORK/'sources').mkdir(parents=True,exist_ok=True)
(WORK/'generation_specs.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2),encoding='utf-8')
(WORK/'generation_prompts.md').write_text('# R1–R10 generation prompts\n\nBuilt-in imagegen, one call per material. R2/R7/R8 use the specific six-colour neutral ramp; this overrides the common 8–12 minimum.\n\n'+'\n\n'.join('## '+e['id']+' '+e['name']+'\n\n'+e['prompt'] for e in entries),encoding='utf-8')
print('Prepared',len(entries),'swatches')
